-- Isolated company inbox fixtures. No provider traffic, secrets or real member modifications.
begin;
do $$
declare u uuid:=gen_random_uuid();v uuid:=gen_random_uuid();r uuid:=gen_random_uuid();c uuid;t uuid;mid uuid;outid uuid:=gen_random_uuid();gen uuid;lease uuid;secret uuid;cfg uuid;result jsonb;input jsonb;oldtime timestamptz;
begin
 insert into public.duuk_roles(id,name,description) values(r,'Fixture WhatsApp','Rollback only');
 insert into auth.users(id,email) values(u,u::text||'@test.invalid'),(v,v::text||'@test.invalid');
 insert into public.duuk_profiles(id,name,email,role_id,active,is_super_admin) values(u,'Inbox fixture',u::text||'@test.invalid',r,true,false),(v,'Denied fixture',v::text||'@test.invalid',r,true,false);
 begin perform public.duuk_whatsapp_backend(u,'status');raise exception 'Access missing';exception when sqlstate 'PT403' then null;end;
 insert into public.duuk_role_permissions(role_id,permission,allowed) values(r,'whatsapp',true);
 perform public.duuk_whatsapp_backend(u,'status');
 insert into public.duuk_user_permissions(user_id,permission,allowed) values(v,'whatsapp',false);
 begin perform public.duuk_whatsapp_backend(v,'contacts');raise exception 'Individual denial bypass';exception when sqlstate 'PT403' then null;end;
 begin perform public.duuk_whatsapp_backend(null,'send_begin');raise exception 'Anonymous send bypass';exception when sqlstate 'PT403' then null;end;
 begin perform public.duuk_whatsapp_backend(u,'configure');raise exception 'Nonadmin configure';exception when sqlstate 'PT403' then null;end;
 if has_function_privilege('authenticated','public.duuk_whatsapp_backend(uuid,text,jsonb)','execute') or has_table_privilege('authenticated','duuk_private.whatsapp_contacts','select') then raise exception 'Private records exposed';end if;
 result:=public.duuk_whatsapp_backend(u,'contact_save','{"name":"Fixture contact","wa_id":"5511999990001","email":"fixture@test.invalid","tags":["Fixture"]}');c:=(result->>'id')::uuid;
 if result ? 'photo_base64' then raise exception 'Photo leaked in directory';end if;
 result:=public.duuk_whatsapp_backend(u,'open_thread',jsonb_build_object('contact_id',c));t:=(result->>'id')::uuid;
 begin perform public.duuk_whatsapp_backend(u,'contact_save',jsonb_build_object('id',c,'version',0,'name','Stale','wa_id','5511999990001'));raise exception 'Stale update accepted';exception when sqlstate 'PT409' then null;end;
 result:=public.duuk_whatsapp_backend(u,'contacts','{"search":"fixture@test.invalid"}');if jsonb_array_length(result->'items')<>1 then raise exception 'Email search';end if;
 select id,generation into cfg,gen from duuk_private.whatsapp_config where singleton;
 secret:=vault.create_secret('{"access_token":"fixture","app_secret":"fixture"}');
 update duuk_private.whatsapp_config set status='connected',phone_id='123456',waba_id='234567',credentials_id=secret,token_expires_at=now()+interval '1 hour' where singleton;
 begin perform public.duuk_whatsapp_backend(u,'send_begin',jsonb_build_object('thread_id',t,'id',outid,'type','text','text','Hi','request_hash','h'));raise exception 'No window accepted';exception when sqlstate 'PT409' then null;end;
 input:=jsonb_build_object('connection_id',cfg,'generation',gen,'messages',jsonb_build_array(jsonb_build_object('provider_id','wamid.fixtureIncoming','from','5511999990001','name','Remote name','type','text','text','Hello','occurred_at',now(),'opens_window',true)));
 perform public.duuk_whatsapp_backend(null,'ingest',input);perform public.duuk_whatsapp_backend(null,'ingest',input);
 if (select count(*) from duuk_private.whatsapp_messages where thread_id=t)<>1 then raise exception 'Duplicate incoming';end if;
 if (select name from duuk_private.whatsapp_contacts where id=c)<>'Fixture contact' then raise exception 'Local contact name overwritten';end if;
 select id into mid from duuk_private.whatsapp_messages where thread_id=t;
 result:=public.duuk_whatsapp_backend(u,'star',jsonb_build_object('id',mid,'starred',true));if (result->>'starred')::boolean is not true then raise exception 'Star missing';end if;
 delete from public.duuk_user_permissions where user_id=v;
 result:=public.duuk_whatsapp_backend(v,'get_message',jsonb_build_object('id',mid));if (result->>'starred')::boolean then raise exception 'Star leaked across members';end if;
 begin perform public.duuk_whatsapp_backend(u,'contact_save',jsonb_build_object('id',c,'version',1,'name','Fixture','wa_id','5511999990002'));raise exception 'History phone changed';exception when sqlstate 'PT409' then null;end;
 begin perform public.duuk_whatsapp_backend(u,'send_begin',jsonb_build_object('thread_id',t,'id',outid,'type','template','request_hash','h'));raise exception 'Paid template accepted';exception when sqlstate 'PT400' then null;end;
 input:=jsonb_build_object('thread_id',t,'id',outid,'type','text','text','Reply fixture','reply_to',mid,'request_hash','h');result:=public.duuk_whatsapp_backend(u,'send_begin',input);lease:=(result->'internal'->>'lease_id')::uuid;
 if (result->>'execute')::boolean is not true then raise exception 'No dispatch claim';end if;
 result:=public.duuk_whatsapp_backend(u,'send_begin',input);if (result->>'execute')::boolean then raise exception 'Duplicate POST allowed';end if;
 begin perform public.duuk_whatsapp_backend(v,'send_begin',input);raise exception 'Other actor reused ID';exception when sqlstate 'PT409' then null;end;
 begin perform public.duuk_whatsapp_backend(u,'send_begin',input||jsonb_build_object('id',gen_random_uuid()));raise exception 'Uncertain hash duplicated';exception when sqlstate 'PT409' then null;end;
 result:=public.duuk_whatsapp_backend(u,'send_dispatch',jsonb_build_object('id',outid,'lease_id',lease));if result->>'status'<>'SENDING' then raise exception 'Dispatch not persisted';end if;
 perform public.duuk_whatsapp_backend(u,'send_error',jsonb_build_object('id',outid,'lease_id',lease,'uncertain',true,'error','Fixture timeout'));
 perform public.duuk_whatsapp_backend(null,'ingest',jsonb_build_object('connection_id',cfg,'generation',gen,'statuses',jsonb_build_array(jsonb_build_object('provider_id','wamid.fixtureOutgoing','recipient','5511999990002','request_id',outid,'status','READ'))));
 if (select status from duuk_private.whatsapp_messages where id=outid)<>'UNCERTAIN' then raise exception 'Forged recipient status';end if;
 perform public.duuk_whatsapp_backend(null,'ingest',jsonb_build_object('connection_id',cfg,'generation',gen,'statuses',jsonb_build_array(jsonb_build_object('provider_id','wamid.fixtureOutgoing','recipient','5511999990001','request_id',outid,'status','READ'))));
 perform public.duuk_whatsapp_backend(u,'send_ack',jsonb_build_object('id',outid,'lease_id',lease,'provider_id','wamid.fixtureOutgoing'));
 perform public.duuk_whatsapp_backend(u,'send_error',jsonb_build_object('id',outid,'lease_id',lease,'uncertain',true,'error','Late timeout'));
 if (select status from duuk_private.whatsapp_messages where id=outid)<>'READ' then raise exception 'Confirmed status regressed';end if;
 if (select preview from duuk_private.whatsapp_threads where id=t)<>'Reply fixture' then raise exception 'Recovered preview missing';end if;
 update duuk_private.whatsapp_threads set last_customer_at=now()-interval '23 hours 59 minutes' where id=t;
 begin perform public.duuk_whatsapp_backend(u,'send_begin',input||jsonb_build_object('id',gen_random_uuid(),'request_hash','new'));raise exception 'Expired free window accepted';exception when sqlstate 'PT409' then null;end;
 oldtime:=(select last_customer_at from duuk_private.whatsapp_threads where id=t);
 perform public.duuk_whatsapp_backend(null,'ingest',jsonb_build_object('connection_id',cfg,'generation',gen,'messages',jsonb_build_array(jsonb_build_object('provider_id','wamid.fixtureReaction','from','5511999990001','type','reaction','context_id','wamid.fixtureOutgoing','emoji','👍','occurred_at',now(),'opens_window',false))));
 if (select last_customer_at from duuk_private.whatsapp_threads where id=t) is distinct from oldtime then raise exception 'Reaction extended service window';end if;
 result:=public.duuk_whatsapp_backend(u,'get_message',jsonb_build_object('id',outid));if jsonb_array_length(result->'reactions')<>1 then raise exception 'Reaction not applied';end if;
 result:=public.duuk_whatsapp_backend(u,'analytics',jsonb_build_object('thread_id',t));if (result->>'incoming')::int<>1 or (result->>'read')::int<>1 then raise exception 'Fabricated analytics';end if;
 perform public.duuk_whatsapp_backend(u,'seen',jsonb_build_object('thread_id',t,'seen_at',now()+interval '1 year'));
 if (select seen_at from duuk_private.whatsapp_reads where user_id=u and thread_id=t)>oldtime then raise exception 'Read cursor advanced into future';end if;
 -- Same-second messages retain arrival order in both history and cursor pagination.
 insert into duuk_private.whatsapp_messages(thread_id,provider_id,direction,type,body,occurred_at) values(t,'wamid.orderOne','in','text','First in batch',now()),(t,'wamid.orderTwo','in','text','Second in batch',now()),(t,'wamid.orderThree','in','text','Third in batch',now());
 result:=public.duuk_whatsapp_backend(u,'messages',jsonb_build_object('thread_id',t));
 if result->'items'->-1->>'body'<>'Third in batch' or result->'items'->-2->>'body'<>'Second in batch' then raise exception 'Same-second order lost';end if;
 result:=public.duuk_whatsapp_backend(u,'messages',jsonb_build_object('thread_id',t,'before',result->'items'->-1->>'occurred_at','before_id',result->'items'->-1->>'id','before_sequence',result->'items'->-1->>'sequence'));
 if result->'items'->-1->>'body'<>'Second in batch' then raise exception 'Cursor did not preserve ordering';end if;
 -- Mobile app messages and edits never establish a billable API service window.
 perform public.duuk_whatsapp_backend(null,'ingest',jsonb_build_object('connection_id',cfg,'generation',gen,'messages',jsonb_build_array(jsonb_build_object('provider_id','wamid.fixtureMobileEcho','from','5511999990001','direction','out','type','text','text','Sent on phone','occurred_at',now(),'opens_window',false))));
 if (select last_customer_at from duuk_private.whatsapp_threads where id=t) is distinct from oldtime then raise exception 'Echo extended free window';end if;
 if (select direction from duuk_private.whatsapp_messages where provider_id='wamid.fixtureMobileEcho')<>'out' then raise exception 'Echo shown as customer';end if;
 perform public.duuk_whatsapp_backend(null,'ingest',jsonb_build_object('connection_id',cfg,'generation',gen,'mutations',jsonb_build_array(jsonb_build_object('original','wamid.fixtureIncoming','contact','5511999990001','direction','in','at',now(),'remove',false,'body','Edited source'))));
 if (select body from duuk_private.whatsapp_messages where id=mid)<>'Edited source' then raise exception 'Edit missing';end if;
 perform public.duuk_whatsapp_backend(null,'ingest',jsonb_build_object('connection_id',cfg,'generation',gen,'mutations',jsonb_build_array(jsonb_build_object('original','wamid.fixtureIncoming','contact','5511999990001','direction','in','at',now(),'remove',true))));
 if (select retracted_at from duuk_private.whatsapp_messages where id=mid) is null or (select body from duuk_private.whatsapp_messages where id=mid)<>'' then raise exception 'Retracted content retained';end if;
 perform public.duuk_whatsapp_backend(null,'ingest',jsonb_build_object('connection_id',cfg,'generation',gen,'contacts',jsonb_build_array(jsonb_build_object('wa_id','5511999990001','name','Remote edit','at',now()))));
 if (select name from duuk_private.whatsapp_contacts where id=c)<>'Fixture contact' then raise exception 'Source update overwrote local';end if;
 insert into duuk_private.whatsapp_messages(thread_id,direction,type,body,occurred_at) values(t,'in','text','Late receipt',now()-interval '91 days');
 perform duuk_private.whatsapp_cleanup();
 if exists(select 1 from duuk_private.whatsapp_messages where thread_id=t and body='Late receipt') then raise exception 'Late receipt escaped retention';end if;
 update public.duuk_profiles set active=false where id=u;
 begin perform public.duuk_whatsapp_backend(u,'get_message',jsonb_build_object('id',mid));raise exception 'Inactive member retained access';exception when sqlstate 'PT403' then null;end;
end $$;
rollback;
